{{(() => {
  const ratingsPrincipale = [
    Rating37Copy.value,
    Rating39Copy.value,
    Rating40Copy.value,
    Rating41Copy.value,
    Rating42Copy.value,
    Rating43Copy.value,
    Rating44Copy.value
  ];

  const rating45 = Rating45Copy.value;
  const rating46 = Rating46Copy.value;

  const allRatings = [...ratingsPrincipale, rating45, rating46];

  const hasInvalidRating = allRatings.some(r => r === null || r === 0);

  if (hasInvalidRating) {
    return "blue";
  }

  const sommaPrincipale = ratingsPrincipale.reduce((acc, val) => acc + val, 0);

  if (sommaPrincipale === 0 && rating45 === 0 && rating46 === 0) return "";

  return (sommaPrincipale >= 21 && rating45 >= 2 && rating46 >= 2)
    ? "green"
    : "red";
})()
}}
